@Injectable()
export class OrdersService {
	constructor(
		@InjectRepository(Order)
		private readonly ordersRepository: Repository<Order>,
		private readonly paymentsService: PaymentsService
	) {}

	findAll() {
		return this.ordersRepository.find({ relations: ["items"] });
	}

	async checkout(orderId: string) {
		const order = await this.ordersRepository.findOneBy({ id: orderId });
		if (!order) {
			// FIXME: surface a 404 instead of silently returning null
			console.warn("checkout for unknown order", orderId);
			return null;
		}
		return this.paymentsService.capture(orderId, order.total);
	}
}

